/// <summary>
/// Extension class for MarkupTransInsert class
/// </summary>
[ExtensionOf(classStr(MarkupTransInsert))]
internal final class METMarkupTransInsertCls_Extension
{
    private boolean metCalledFromPriceSimulator;

}

Method.Source:
/// <summary>
/// Get/set metCalledFromPriceSimulator
/// </summary>
/// <param name = "_metCalledFromPriceSimulator">boolean metCalledFromPriceSimulator</param>
/// <returns>metCalledFromPriceSimulator</returns>
public boolean metParmCalledFromPriceSimulator(boolean _metCalledFromPriceSimulator = metCalledFromPriceSimulator)
{
    metCalledFromPriceSimulator = _metCalledFromPriceSimulator;
    return metCalledFromPriceSimulator;
}

/// <summary>
/// CoC
/// </summary>
/// <returns>boolean true if skiip original matching charges insert</returns>
protected boolean shouldSkipOriginalInsertMatchingCharges()
{
    boolean ret = next shouldSkipOriginalInsertMatchingCharges();
    if(this.metParmCalledFromPriceSimulator())
    {
        ret = false;
    }
    return ret;
}

/// <summary>
/// CoC
/// </summary>
/// <param name = "_searchParameter">_searchParameter</param>
/// <returns>MarkupAutoTable</returns>
protected MarkupAutoTable findMarkupAutoTableByNaturalKey(MarkupAutoTable _searchParameter)
{
    MarkupAutoTable  markupAutoTable = next findMarkupAutoTableByNaturalKey(_searchParameter);

    if(this.metParmCalledFromPriceSimulator())
    {
        select firstonly markupAutoTable
            index hint MarkupIdx
            where markupAutoTable.ModuleCategory        == _searchParameter.ModuleCategory        &&
                  markupAutoTable.ModuleType            == _searchParameter.ModuleType            &&
                  markupAutoTable.AccountCode           == _searchParameter.AccountCode           &&
                  markupAutoTable.AccountRelation       == _searchParameter.AccountRelation       &&
                  markupAutoTable.ItemCode              == _searchParameter.ItemCode              &&
                  markupAutoTable.ItemRelation          == _searchParameter.ItemRelation          &&
                  markupAutoTable.MarkupReturn          == _searchParameter.MarkupReturn          &&
                  markupAutoTable.DlvModeCode           == _searchParameter.DlvModeCode           &&
                  markupAutoTable.DlvModeRelation       == _searchParameter.DlvModeRelation       &&
                  markupAutoTable.ReturnRelation        == _searchParameter.ReturnRelation;               
    }

    return markupAutoTable;
}

/// <summary>
/// COC to update the GST Group if Auto charge GST group not provided
/// </summary>
/// <param name = "_markupAutoLine">_markupAutoLine</param>
/// <returns>MarkupTrans object with updated TaxItemGroup if previously blank</returns>
protected MarkupTrans initializeMarkupTrans(MarkupAutoLine _markupAutoLine)
{
    if( !_markupAutoLine.TaxItemGroup &&
        !_markupAutoLine.markupTable().TaxItemGroup &&
        parameters.Source.TableId == tableNum(SalesLine))
    {
        SalesLine salesLine = parameters.Source;

        _markupAutoLine.TaxItemGroup = METInventTable::find(salesLine.ItemId).AutoChargeTaxGroupId;
    }

    return next initializeMarkupTrans(_markupAutoLine);
}

/// <summary>
/// CB748_PricingConditions
/// </summary>
/// <param name = "_markupAutoTable">Auto charge header record</param>
/// <returns>Query for auto charge lines</returns>
protected Query buildMarkupAutoLineQuery(MarkupAutoTable _markupAutoTable)
{
    Query query = next buildMarkupAutoLineQuery(_markupAutoTable);

    // For PO header auto charges
    if (parameters.Source.TableId == tableNum(PurchLine)
    &&  parameters.ModuleCategory == HeadingLine::Line
    &&  parameters.ModuleType     == MarkupModuleType::Vend)
    {
        // Exclude rebate charge codes from PO creation
        QueryBuildDataSource qbds = query.dataSourceTable(tableNum(MarkupAutoLine));

        QueryBuildDataSource qbdsMarkupTable = qbds.addDataSource(tableNum(MarkupTable));
        qbdsMarkupTable.joinMode(JoinMode::ExistsJoin);
        qbdsMarkupTable.relations(true);

        qbdsMarkupTable.addRange(fieldNum(MarkupTable, METIsRebateCode)).value(queryValue(NoYes::No));
    }

    return query;
}
